import{_ as a,o,c as e,aj as r}from"./chunks/framework.Cn87zHeG.js";const i="/onerobot-H1/images/getting-started/debug-tool/overview.jpg",s="/onerobot-H1/images/getting-started/debug-tool/mapping.jpg",n="/onerobot-H1/images/getting-started/debug-tool/map.jpg",g="/onerobot-H1/images/getting-started/debug-tool/localization.jpg",d="/onerobot-H1/images/getting-started/debug-tool/navigation.jpg",l="/onerobot-H1/images/getting-started/debug-tool/charging.jpg",h="/onerobot-H1/images/getting-started/debug-tool/actuators-status.jpg",c="/onerobot-H1/images/getting-started/debug-tool/actuators-controls.jpg",p="/onerobot-H1/images/getting-started/debug-tool/health.jpg",b="/onerobot-H1/images/getting-started/debug-tool/cameras.jpg",m="/onerobot-H1/images/getting-started/debug-tool/rosbag.jpg",u="/onerobot-H1/images/getting-started/debug-tool/rosbag-records.jpg",w=JSON.parse('{"title":"H1 调试工具使用说明","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"getting-started/debug-tool.md","filePath":"getting-started/debug-tool.md"}'),f={name:"getting-started/debug-tool.md"};function _(q,t,P,H,k,x){return o(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="h1-调试工具使用说明" tabindex="-1">H1 调试工具使用说明 <a class="header-anchor" href="#h1-调试工具使用说明" aria-label="Permalink to &quot;H1 调试工具使用说明&quot;">​</a></h1><p><strong>H1 调试工具</strong>是机器人自带的网页工具，端口为 <strong>8090</strong>。通过浏览器可以完成建图、定位、导航、硬件检查、相机预览及日志采集，用于设备调试和功能验证。</p><p>首次使用建议按 <strong>连接工具 → 检查状态 → 建图或加载地图 → 启动定位 → 导航</strong> 的顺序操作。升降与头部控制、系统诊断功能可按需要进入，具体功能以设备配置和已安装固件为准。</p><table tabindex="0"><thead><tr><th>要做什么</th><th>说明位置</th></tr></thead><tbody><tr><td>打开网页、查看设备和接口状态</td><td><a href="#connect">连接与访问</a>、<a href="#status">状态检查</a></td></tr><tr><td>准备场景地图并定位机器人</td><td><a href="#mapping">建图</a>、<a href="#maps">地图管理</a>、<a href="#localization">定位</a></td></tr><tr><td>记录目标点、导航和取消任务</td><td><a href="#navigation">点位与导航</a></td></tr><tr><td>设置上桩方向、执行上桩并确认充电</td><td><a href="#charging">回充</a></td></tr><tr><td>检查与控制升降、头部</td><td><a href="#hardware">升降与头部控制</a></td></tr><tr><td>查看相机、收集故障信息</td><td><a href="#diagnostics">系统诊断</a>、<a href="#logs">日志下载</a>、<a href="#rosbag">ROS Bag 录制</a></td></tr></tbody></table><p>下文截图用于对照页面和操作入口，设备状态、地图、点位及记录以实际机器人为准。<strong>点击截图可查看原图。</strong></p><h2 id="connect" tabindex="-1">连接机器人并打开工具 <a class="header-anchor" href="#connect" aria-label="Permalink to &quot;连接机器人并打开工具 {#connect}&quot;">​</a></h2><p>机器人开机后，让电脑与机器人连接到同一网络，使用 Chrome 或 Edge 打开对应地址：</p><table tabindex="0"><thead><tr><th>接入方式</th><th>访问地址</th></tr></thead><tbody><tr><td>网线直连</td><td><code>http://10.42.0.2:8090</code></td></tr><tr><td>机器人热点</td><td><code>http://192.168.60.1:8090</code></td></tr><tr><td>同一局域网</td><td><code>http://&lt;机器人IP&gt;:8090</code></td></tr></tbody></table><p>网线直连时，先按<a href="./network-ota.html#wired-direct">电脑有线网络设置</a>配置网卡，可直接查看 <a href="./network-ota.html#wired-ubuntu">Ubuntu</a> 或 <a href="./network-ota.html#wired-windows">Windows</a> 的操作截图。电脑使用 <code>10.42.0.1</code>，机器人使用 <code>10.42.0.2</code>，不要设置成同一地址。</p><p>如果已经能打开网络配置工具，无需重复配置电脑 IP，将网页端口从 <strong>8080</strong> 改为 <strong>8090</strong> 即可。H1 调试工具无需另行登录。建议使用<a href="./../firmware.html">最新适配固件</a>；较早固件可能没有下文中的部分功能。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/overview.jpg"><img src="'+i+'" alt="H1 调试工具首页，左侧功能导航及顶部接口状态"></a></p><h2 id="status" tabindex="-1">使用前检查 <a class="header-anchor" href="#status" aria-label="Permalink to &quot;使用前检查 {#status}&quot;">​</a></h2><p>打开页面后，先检查顶部状态条和左侧栏底部的「软件版本」。软件版本是机器人已安装的整机固件版本，版本查询与升级说明见<a href="./../firmware.html">固件版本</a>。</p><p>顶部各接口状态标记的含义如下：</p><table tabindex="0"><thead><tr><th>颜色</th><th>含义</th><th>操作建议</th></tr></thead><tbody><tr><td>绿色 <code>ok</code></td><td>接口当前正常</td><td>按对应功能的前提继续操作</td></tr><tr><td>黄色 <code>stale</code></td><td>消息更新超时</td><td>到「系统诊断 → 接口健康」查看具体接口</td></tr><tr><td>红色 <code>response_timeout</code></td><td>指令发出后等待响应超时</td><td>先确认相关服务与设备状态，再进行依赖它的操作</td></tr><tr><td>灰色 <code>never_seen</code></td><td>尚未收到消息，或发布接口尚未发送</td><td>结合接口方向及使用情况判断；灰色本身不代表故障</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">运动操作前</p><p>导航、回充及执行器操作会驱动机器人。开始前清空运动范围，确保无人、无障碍物，并保持物理急停可用。不要同时下发互相冲突的任务；出现异常时先停止操作。</p></div><h2 id="mapping-and-localization" tabindex="-1">建图、地图与定位 <a class="header-anchor" href="#mapping-and-localization" aria-label="Permalink to &quot;建图、地图与定位 {#mapping-and-localization}&quot;">​</a></h2><h3 id="mapping" tabindex="-1">建图 <a class="header-anchor" href="#mapping" aria-label="Permalink to &quot;建图 {#mapping}&quot;">​</a></h3><ol><li>将机器人放到建图起点，通常为充电桩位置。</li><li>进入「算法测试 → 建图」，点击 <strong>「开始建图」</strong>。当前流程使用充电桩起点，无需手填起始位姿。</li><li>使用遥控器控制机器人遍历场地，查看实时地图预览中的扫描区域。</li><li>扫描完成后点击 <strong>「完成建图」</strong>，等待地图保存与加载完成，再进行定位或导航。</li></ol><p>建图期间，定位和导航会受互斥条件限制。需要进行下一项操作时，先完成建图。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/mapping.jpg"><img src="'+s+'" alt="建图页面的开始建图、完成建图和状态区域"></a></p><h3 id="maps" tabindex="-1">地图管理 <a class="header-anchor" href="#maps" aria-label="Permalink to &quot;地图管理 {#maps}&quot;">​</a></h3><p>已有配套场景地图时，可在 <strong>「算法测试 → 地图」</strong> 页导入地图包：</p><ol><li>先结束建图、导航等正在运行的任务。需要保留当前地图时，先导出备份。</li><li>在「导入地图包」区域点击 <strong>「选择文件」</strong>，选择原始地图 ZIP，无需解压或重新打包。</li><li>点击 <strong>「导入地图」</strong>，确认替换当前地图。</li><li>页面提示「已下发地图导入」后，核对地图画面与元信息，再进入定位页确认定位结果。</li></ol><p>「已下发」表示请求已发送，不等于地图已经生效。地图需要与实际场景匹配；洗衣场景的地图和布置要求见<a href="./../example/laundry.html#map">洗衣服场景示例</a>。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/map.jpg"><img src="'+n+'" alt="地图页面的 ZIP 地图导入入口和地图元信息"></a></p><h3 id="localization" tabindex="-1">启动定位 <a class="header-anchor" href="#localization" aria-label="Permalink to &quot;启动定位 {#localization}&quot;">​</a></h3><ol><li>确认地图已建好或已加载。</li><li>将机器人放回与地图对应的充电桩位置；页面的「启动定位」使用充电桩定位方式。</li><li>进入「算法测试 → 定位」，点击 <strong>「启动定位」</strong>。</li><li>等待状态变为 <strong><code>locating_success</code></strong>，再记录导航点位或下发导航任务。</li></ol><p>定位未成功时，先检查地图、机器人位置及相关接口状态，不要继续下发导航。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/localization.jpg"><img src="'+g+'" alt="定位页面的启动定位按钮、定位状态和当前位姿"></a></p><h2 id="navigation" tabindex="-1">点位与导航 <a class="header-anchor" href="#navigation" aria-label="Permalink to &quot;点位与导航 {#navigation}&quot;">​</a></h2><h3 id="waypoints" tabindex="-1">记录预设点位 <a class="header-anchor" href="#waypoints" aria-label="Permalink to &quot;记录预设点位 {#waypoints}&quot;">​</a></h3><ol><li>完成定位，将机器人开到目标位置与朝向。</li><li>在导航页确认定位状态为 <code>locating_success</code>。</li><li>点击 <strong>「记录当前点位为 P1 / P2 / P3 / P4」</strong> 中对应的按钮。</li><li>对其余目标点重复操作，核对点位与场景是否匹配。</li></ol><p>录入后先核对点位坐标。重启或更换地图、场景后，重新检查各点位；缺失或不匹配时，重新录入后再导航。</p><h3 id="下发导航目标" tabindex="-1">下发导航目标 <a class="header-anchor" href="#下发导航目标" aria-label="Permalink to &quot;下发导航目标&quot;">​</a></h3><p>进入「算法测试 → 导航」，确认定位成功后，选择一种方式下发：</p><ul><li><strong>预设点位</strong>：在「导航到」区域点击 <strong>P1 / P2 / P3 / P4</strong>。灰色点位表示尚未录入，需先记录。</li><li><strong>自定义位姿</strong>：填写 <code>x / y / yaw</code>，其中 <code>yaw</code> 使用弧度；按需勾选 <strong><code>is_accurate_pose</code></strong>，点击 <strong>「下发自定义点位」</strong>。</li></ul><p>下发后观察任务状态与机器人运动情况，等待任务完成，再进行下一项操作。</p><h3 id="cancel-navigation" tabindex="-1">取消导航 <a class="header-anchor" href="#cancel-navigation" aria-label="Permalink to &quot;取消导航 {#cancel-navigation}&quot;">​</a></h3><p>在导航页点击红色 <strong>「取消当前任务」</strong> 按钮，并确认机器人停止、任务状态已更新。需要立即处置异常且页面操作无效时，使用本体物理急停。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/navigation.jpg"><img src="'+d+'" alt="导航页面的预设点录入、导航目标和取消任务按钮"></a></p><h2 id="charging" tabindex="-1">回充 <a class="header-anchor" href="#charging" aria-label="Permalink to &quot;回充 {#charging}&quot;">​</a></h2><p>配有<strong>回充板</strong>的 H1 可通过「算法测试 → 回充」设置上桩方向，并在充电座前执行精对位和电极对接。</p><ol><li><strong>准备上桩。</strong> 先结束建图、导航等正在运行的任务，将机器人放到充电座前的对接预备点附近，确认机器人与充电座之间的通道畅通。</li><li><strong>核对方向。</strong> 查看「回充方向配置」下的「当前配置」。默认是 <strong>前进上桩、后退下桩</strong>。若设备需要倒车对接，选择 <strong>倒车上桩、前进下桩</strong>，点击「保存配置」，再核对「当前配置」。已有导航或上桩任务时，等任务结束，或取消任务并确认机器人停止后再改方向。</li><li><strong>执行上桩。</strong> 在「上桩动作」中点击 <strong>「执行上桩（精对位与电极对接）」</strong>。页面提示「已下发上桩」后，查看本次任务的 <code>task_id</code>、目标「上桩对接」和状态。需要中止时，点击 <strong>「取消当前任务」</strong>，确认机器人已停止。</li><li><strong>确认结果。</strong> 任务状态为 <code>success</code> 时，再查看左侧栏是否显示「在桩」和「充电中」，分别确认机器人已就位、已开始充电。若状态为 <code>fail</code>，查看「失败原因」。若侧栏显示「没有获取在桩和充电数据」，则暂时无法通过网页确认充电状态。</li></ol><p><a href="/onerobot-H1/images/getting-started/debug-tool/charging.jpg"><img src="'+l+'" alt="H1 调试工具回充页：两种回充方向、执行上桩、取消任务和任务状态"></a></p><h2 id="hardware" tabindex="-1">升降与头部控制 <a class="header-anchor" href="#hardware" aria-label="Permalink to &quot;升降与头部控制 {#hardware}&quot;">​</a></h2><p><span id="actuators"></span></p><p>进入 <strong>「硬件测试 → 执行器」</strong>，先查看状态，再按需要操作：</p><table tabindex="0"><thead><tr><th>检查项</th><th>说明</th></tr></thead><tbody><tr><td>限位开关</td><td>升降顶 / 底、头部俯仰到顶 / 到底、头部左 / 右，共 6 路；绿色表示未触发，黄色表示已触发限位，灰色表示无数据</td></tr><tr><td>电机告警</td><td>查看头部堵转状态、升降报警码与说明</td></tr><tr><td>校准与手动微调</td><td>按页面对应控件操作，动作前确认上方及头部运动范围无遮挡</td></tr></tbody></table><p><a href="/onerobot-H1/images/getting-started/debug-tool/actuators-status.jpg"><img src="'+h+'" alt="执行器页面的限位开关、当前位置和电机告警"></a></p><p>出现堵转或升降报警时，先停止操作、排除机械卡阻，再按页面提示处理。需要清除升降报警时，在「校准」区域点击 <strong>「清除升降报警」</strong>，并重新核对状态。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/actuators-controls.jpg"><img src="'+c+'" alt="执行器页面的升降和头部校准、清除报警及手动微调按钮"></a></p><h2 id="diagnostics" tabindex="-1">系统诊断与数据采集 <a class="header-anchor" href="#diagnostics" aria-label="Permalink to &quot;系统诊断与数据采集 {#diagnostics}&quot;">​</a></h2><h3 id="接口健康" tabindex="-1">接口健康 <a class="header-anchor" href="#接口健康" aria-label="Permalink to &quot;接口健康&quot;">​</a></h3><p>进入 <strong>「系统诊断 → 接口健康」</strong>，查看各话题的状态、所属组、更新时间和异常详情。需要技术支持时，点击 <strong>「复制诊断信息」</strong>，将结果连同固件版本、操作步骤和异常时间提供给支持人员。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/health.jpg"><img src="'+p+'" alt="接口健康页面的状态表、复制诊断信息和打包下载日志入口"></a></p><h3 id="cameras" tabindex="-1">相机预览 <a class="header-anchor" href="#cameras" aria-label="Permalink to &quot;相机预览 {#cameras}&quot;">​</a></h3><p>进入 <strong>「系统诊断 → 摄像头」</strong>，查看已安装相机的图像。头部、左 / 右相机及选配深度相机是否显示，以设备配置为准；未安装的选配相机没有图像不代表故障。</p><p>打开预览时会建立图像订阅，关闭后释放。图像传输会占用网络带宽和处理资源，帧率取决于相机与网络条件。相机话题和 QoS 见<a href="./../hardware/sensors.html">传感器</a>。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/cameras.jpg"><img src="'+b+'" alt="摄像头页面的头部及左右相机图像预览"></a></p><h3 id="logs" tabindex="-1">下载机器人日志 <a class="header-anchor" href="#logs" aria-label="Permalink to &quot;下载机器人日志 {#logs}&quot;">​</a></h3><ol><li>进入「系统诊断 → 接口健康」，点击 <strong>「打包下载日志」</strong>。</li><li>等待打包和下载完成；日志较大时进度可能暂时停顿。</li><li>保存下载的 ZIP，文件名通常包含设备 ID、固件版本和时间；提供给技术支持时附上对应操作和异常时间。</li></ol><h3 id="rosbag" tabindex="-1">录制 ROS Bag <a class="header-anchor" href="#rosbag" aria-label="Permalink to &quot;录制 ROS Bag {#rosbag}&quot;">​</a></h3><ol><li>进入 <strong>「系统诊断 → ROS Bag」</strong>，按排查需要勾选话题。相机、点云等大流量话题按需选择。</li><li>点击 <strong>「开始录制」</strong>，完成需要记录的操作。</li><li>点击 <strong>「停止录制」</strong>，等待写入完成。</li><li>在列表中下载 tar 记录包，解压后可使用 <code>ros2 bag play</code> 回放。</li></ol><p>同一时刻只允许一个录制任务；开始手动录制前，须先关闭自动录制。停止时不要断电。<strong>手动录制</strong>时，剩余磁盘空间低于 <strong>2 GiB</strong> 会自动停止，且无法开始新的手动录制。自动录制采用分段回收，按配额清理旧分段；仅在排查需要时开启，用完及时关闭。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/rosbag.jpg"><img src="'+m+'" alt="ROS Bag 页面的自动录制开关、话题选择及开始和停止录制按钮"></a></p><p>在下方「录制状态」检查当前任务和磁盘剩余；「已录制的 Bag」列出可下载的记录。下载并确认所需数据已保存后，及时清理机器人上的录制文件，避免占满磁盘。</p><p><a href="/onerobot-H1/images/getting-started/debug-tool/rosbag-records.jpg"><img src="'+u+'" alt="ROS Bag 页面的录制状态、磁盘剩余和已录制文件列表"></a></p><h2 id="遇到问题" tabindex="-1">遇到问题 <a class="header-anchor" href="#遇到问题" aria-label="Permalink to &quot;遇到问题&quot;">​</a></h2><p>访问失败、状态异常、定位不成功、相机无图或日志下载问题，见 <a href="./../faq/factory-test.html">H1 调试工具常见问题</a>。需要查后台服务或重启命令时，见<a href="./../diagnostics/services.html">机内服务与重启</a>。</p>',70)])])}const v=a(f,[["render",_]]);export{w as __pageData,v as default};
